import { expect, test } from '@playwright/test';
import { emptyState, newProject, type WemockState } from '../src/core/types';
import { type FixtureServer, startFixtureServer } from './fixture/server';
import { type WemockSession, launchWemock } from './helpers';

let fixture: FixtureServer;
let session: WemockSession;

test.beforeAll(async () => {
  fixture = await startFixtureServer();
  session = await launchWemock(fixture.url);
});

test.afterAll(async () => {
  await session?.context?.close();
  await fixture?.close();
});

test('one XHR object reused: a mocked call, then a real one, reads the real response', async () => {
  const page = await session.context.newPage();
  try {
    const project = newProject('p1', fixture.origin);
    project.scenarios[0]!.mocks.push({
      id: 'm-reuse', enabled: true, method: 'GET', urlPattern: '/api/mocked-only',
      response: { status: 418, headers: { 'x-mock': '1' }, body: 'mocked', bodyEncoding: 'text', delayMs: 0 },
      source: 'manual', createdAt: 1,
    });
    const state: WemockState = { ...emptyState(), projects: [project], enabledOrigins: [fixture.origin] };
    await session.setState(state);
    await page.goto(`${fixture.url}/index.html`);

    const result = await page.evaluate(async () => {
      const xhr = new XMLHttpRequest();
      const run = (url: string) =>
        new Promise<{ status: number; text: string; mockHeader: string | null; state: number }>(
          (resolve) => {
            xhr.onloadend = () =>
              resolve({ status: xhr.status, text: xhr.responseText,
                mockHeader: xhr.getResponseHeader('x-mock'), state: xhr.readyState });
            xhr.open('GET', url);
            xhr.send();
          });
      const first = await run('/api/mocked-only');
      const second = await run('/api/goals');
      return { first, second };
    });

    expect(result.first).toMatchObject({ status: 418, text: 'mocked', mockHeader: '1', state: 4 });
    expect(result.second.status).toBe(200);
    expect(result.second.text).toBe('{"source":"server"}');
    expect(result.second.mockHeader).toBeNull();
  } finally {
    await page.close();
  }
});
